def add(group,start,blob):
    data=[x for x in blob.strip().splitlines() if x.strip()]
    assert len(data)==25,(group,start,len(data))
    sources,fp,bridge=CONFIG[group]
    for j,line in enumerate(data):
        title,math,work,control,good,repair=line.split(' || ')
        ident=f'AS{start+j:03d}'
        rows.append(dict(id=ident,group=group,title=title,principle=fp,math=math,
        inputs='Use the exact source/operator and declared geometry in this work order. Begin with one synthetic controlled fixture, <=256 source elements and two refinements; use actual observations only with their selection, calibration and covariance. Missing physical response or data is a named prerequisite, never an invented number.',
        steps=['Pin the framework branch, source hashes, measured-G convention and exact mathematical output. List every independent datum before deriving anything.',work,'Derive the transformation from physical variables to the stated estimand. Reproduce the crucial identity or finite witness with a separate representation, recording units, signs, conditioning and error bounds.','Run the negative control and preserve failed cases. Return the scoped implication, its first-principles premises and the next distinct child question; an empirical fit alone cannot supply a missing action.'],
        checks=[control,'Hold the underlying physical fixture fixed when changing representation or resolution; report both scale footings separately and require residual error to contract under the stated refinement.'],
        completion='Deliver the named mathematical object, a controlled counterexample, or an exact missing prerequisite. Separate synthetic validation, measured evidence and a universal proof. The same-action closure implication must be explicit.',
        sources=sources,branch='Operative filtered MONO where a field prediction is needed; any explicitly named Q/R radial comparison remains separate.',
        depends_on=[],priority='P1',kind='derivation' if j%3==0 else 'computation',
        claim_key=re.sub('[^a-z0-9]+','_',title.lower()).strip('_'),first_principles=fp,
        closure_bridge=bridge+' Specific obligation: '+title+'.',
        continuation=[good,'If that child supplies a missing physical response, insert its derived equation into this task’s observable and test the same parameter cell against the next independent closure gate; name the equation and gate before dispatch.',repair]))
